/* ---- the point layer: the assembly functions of asm/ declared, one wrapper each ---- */

/* A point: X, Y, Z, T of the extended coordinates, four words each (a table entry the same words
   as Y+X, Y-X, Z, 2dT); an affine entry: Y+X, Y-X, 2dT. Both are the word arrays of the assembly. */
struct fd_ge_adx { ulong X[4], Y[4], Z[4], T[4]; };
typedef struct fd_ge_adx fd_ge_adx_t;
struct fd_ge_adx_aff { ulong YpX[4], YmX[4], T2d[4]; };
typedef struct fd_ge_adx_aff fd_ge_adx_aff_t;

/* The adx point operations of asm/, one function each, over fd_ge_adx_t (a point, or a
   table entry) and fd_ge_adx_aff_t (an affine entry); r may alias an input. */
