static inline void fd_ge_adx_add_affine( fd_ge_adx_t * r, fd_ge_adx_t const * a, fd_ge_adx_aff_t const * b ) { fd_ge_adx_add_affine_asm( r, a, b ); }
static inline void fd_ge_adx_comb( fd_ge_adx_t * r, ulong const table[64][8][12], uchar const scalar[32] ) { fd_ge_adx_comb_asm( r, table, scalar ); }

/* ---- decoding, canonical encoding, negation, odd-multiple tables ---- */

static const ulong fd_adx_d[4] = { 8496970652267935907UL, 31536524315187371UL, 10144147576115030168UL, 5909686906226998899UL };
static const ulong fd_adx_sqrtm1[4] = { 14190309331451158704UL, 3405592160176694392UL, 3120150775007532967UL, 3135389899092516619UL };
