  fd_fe64_mul( t1, t2, t1 ); fd_fe64_mul( u1, u2, u1 );
  fd_fe64_sqr( t1, t1 ); fd_fe64_sqr( u1, u1 ); for( int i=1; i<10; i++ ) { fd_fe64_sqr( t1, t1 ); fd_fe64_sqr( u1, u1 ); }
  fd_fe64_mul( t0, t1, t0 ); fd_fe64_mul( u0, u1, u0 );
