  fd_fe64_sqr( t1, t1 ); fd_fe64_sqr( u1, u1 ); for( int i=1; i<50; i++ ) { fd_fe64_sqr( t1, t1 ); fd_fe64_sqr( u1, u1 ); }
  fd_fe64_mul( t0, t1, t0 ); fd_fe64_mul( u0, u1, u0 );
  fd_fe64_sqr( t0, t0 ); fd_fe64_sqr( u0, u0 ); for( int i=1; i<2; i++ ) { fd_fe64_sqr( t0, t0 ); fd_fe64_sqr( u0, u0 ); }
