/* the end of a square root: r = u v^3 (u v^7)^((p-5)/8) given, x = r when v r^2 = u, x = r sqrt(-1)
   when v r^2 = -u (returns 1), else 0 */
static inline int
fd_fe64_sqrt_fix( ulong x[4], const ulong r[4], const ulong u[4], const ulong v[4] ) {
  ulong r2[4], vx2[4], nu[4];
  fd_fe64_sqr( r2, r ); fd_fe64_mul( vx2, v, r2 );
  if( fd_fe64_eq( vx2, u ) ) { memcpy( x, r, 32 ); return 1; }
  fd_fe64_neg( nu, u );
  if( fd_fe64_eq( vx2, nu ) ) { fd_fe64_mul( x, r, fd_adx_sqrtm1 ); return 1; }
  return 0;
}

/* y and v of an encoding: y the value of the bytes with bit 255 cleared, u = y^2 - 1, v = d y^2 + 1 */
static inline void
fd_adx_point_uv( ulong y[4], ulong u[4], ulong v[4], const uchar b[32] ) {
  ulong y2[4];
  fd_fe64_frombytes( y, b );
  fd_fe64_sqr( y2, y );
  fd_fe64_sub( u, y2, fd_adx_one );
  fd_fe64_mul( v, y2, fd_adx_d ); fd_fe64_add( v, v, fd_adx_one );
}

/* the point (X, Y, 1, T) from y and the root x, x negated when its parity differs from the sign bit */
static inline void
fd_adx_point_pack( fd_ge_adx_t * r, ulong x[4], const ulong y[4], int sign ) {
  if( fd_fe64_sgn( x ) != sign ) { ulong nx[4]; fd_fe64_neg( nx, x ); memcpy( x, nx, 32 ); }
  memcpy( r, x, 32 ); memcpy( r->Y, y, 32 ); memcpy( r->Z, fd_adx_one, 32 ); fd_fe64_mul( r->T, x, y );  /* X at r: gcc schedules r->X differently */
}

/* a from ea and r from er as fd_adx_point_frombytes decodes each, the two square roots'
   exponentiation chains interleaved: bit 0 set when a decoded, bit 1 when r did */
static inline int
fd_adx_point_frombytes2( fd_ge_adx_t * a, const uchar ea[32], fd_ge_adx_t * r, const uchar er[32] ) {
  ulong ya[4], ua[4], va[4], yr[4], ur[4], vr[4];
  fd_adx_point_uv( ya, ua, va, ea ); fd_adx_point_uv( yr, ur, vr, er );
  /* x = u v^3 (u v^7)^((p-5)/8), each */
  ulong v3a[4], v7a[4], v3r[4], v7r[4], ea7[4], er7[4];
  fd_fe64_sqr( v3a, va ); fd_fe64_mul( v3a, v3a, va ); fd_fe64_sqr( v7a, v3a ); fd_fe64_mul( v7a, v7a, va ); fd_fe64_mul( v7a, ua, v7a );
  fd_fe64_sqr( v3r, vr ); fd_fe64_mul( v3r, v3r, vr ); fd_fe64_sqr( v7r, v3r ); fd_fe64_mul( v7r, v7r, vr ); fd_fe64_mul( v7r, ur, v7r );
  fd_fe64_pow22523_2( ea7, v7a, er7, v7r );
  fd_fe64_mul( v3a, ua, v3a ); fd_fe64_mul( v3a, v3a, ea7 );
  fd_fe64_mul( v3r, ur, v3r ); fd_fe64_mul( v3r, v3r, er7 );
  ulong xa[4], xr[4];
  int oa = fd_fe64_sqrt_fix( xa, v3a, ua, va ), orr = fd_fe64_sqrt_fix( xr, v3r, ur, vr );
  if( oa  ) fd_adx_point_pack( a, xa, ya, ea[31] >> 7 );
  if( orr ) fd_adx_point_pack( r, xr, yr, er[31] >> 7 );
  return oa | (orr << 1);
}

/* the points of e[i], i < 4, as fd_adx_point_frombytes decodes each, the four square roots'
   exponentiation chains interleaved: bit i set when e[i] decoded */
static inline int
fd_adx_point_frombytes_x4( fd_ge_adx_t p[], uchar const * const e[] ) {
  ulong y[4][4], u[4][4], v[4][4], v3[4][4], v7[4][4], r7[4][4], x[4][4];
  for( int i=0; i<4; i++ ) {
    fd_adx_point_uv( y[i], u[i], v[i], e[i] );
    fd_fe64_sqr( v3[i], v[i] ); fd_fe64_mul( v3[i], v3[i], v[i] ); fd_fe64_sqr( v7[i], v3[i] ); fd_fe64_mul( v7[i], v7[i], v[i] ); fd_fe64_mul( v7[i], u[i], v7[i] );
  }
  fd_fe64_pow22523_x4( r7, v7 );
  int ok = 0;
  for( int i=0; i<4; i++ ) {
    fd_fe64_mul( v3[i], u[i], v3[i] ); fd_fe64_mul( v3[i], v3[i], r7[i] );
    if( fd_fe64_sqrt_fix( x[i], v3[i], u[i], v[i] ) ) { fd_adx_point_pack( &p[i], x[i], y[i], e[i][31] >> 7 ); ok |= 1<<i; }
  }
  return ok;
}

/* the points of e[i], i < n <= 8, four chains at a time (the last three by four chains, one
   repeated), two or one by the two-chain or the single decode: bit i set when e[i] decoded */
static inline int
fd_adx_point_decode_n( fd_ge_adx_t p[], uchar const * const e[], ulong n ) {
  int ok = 0;
  ulong i = 0UL;
  for( ; i+4UL<=n; i+=4UL ) ok |= fd_adx_point_frombytes_x4( p+i, e+i ) << i;
  if( n-i==3UL ) {
    uchar const * t[4] = { e[i], e[i+1UL], e[i+2UL], e[i] }; fd_ge_adx_t q[4];
    ok |= (fd_adx_point_frombytes_x4( q, t ) & 7) << i;
    p[i] = q[0]; p[i+1UL] = q[1]; p[i+2UL] = q[2];
  } else if( n-i==2UL ) {
    ok |= fd_adx_point_frombytes2( &p[i], e[i], &p[i+1UL], e[i+1UL] ) << i;
  } else if( n-i==1UL ) {
    ok |= fd_adx_point_frombytes( &p[i], e[i] ) << i;
  }
  return ok;
}

/* the canonical affine coordinates of pts[i], i < n <= 8 (n >= 1), through one inversion: prefix
   products of the Z, one inverse, back substitution */
static inline void
fd_adx_point_affine_canon_n( ulong cx[][4], ulong cy[][4], fd_ge_adx_t const pts[], ulong n ) {
  ulong c[8][4], inv[4], zi[4], ax[4], ay[4];
  memcpy( c[0], pts[0].Z, 32 );
  for( ulong i=1UL; i<n; i++ ) fd_fe64_mul( c[i], c[i-1UL], pts[i].Z );
  fd_fe64_inv( inv, c[n-1UL] );
  for( ulong i=n-1UL; i>0UL; i-- ) {
    fd_fe64_mul( zi, inv, c[i-1UL] );      /* 1/Z_i */
    fd_fe64_mul( inv, inv, pts[i].Z );     /* 1/(Z_0 ... Z_{i-1}) */
    fd_fe64_mul( ax, pts[i].X, zi ); fd_fe64_mul( ay, pts[i].Y, zi );
    fd_fe64_canon( cx[i], ax ); fd_fe64_canon( cy[i], ay );
  }
  fd_fe64_mul( ax, pts[0].X, inv ); fd_fe64_mul( ay, pts[0].Y, inv );
  fd_fe64_canon( cx[0], ax ); fd_fe64_canon( cy[0], ay );
}

/* the canonical affine coordinates of a (1/Z checked) and the RFC 8032 encoding */
static inline void
fd_adx_point_affine_canon( ulong cx[4], ulong cy[4], fd_ge_adx_t const * a ) {
  ulong zi[4], ax[4], ay[4];
  fd_fe64_inv( zi, a->Z ); fd_fe64_mul( ax, a->X, zi ); fd_fe64_mul( ay, a->Y, zi );
  fd_fe64_canon( cx, ax ); fd_fe64_canon( cy, ay );
}
static inline void
fd_adx_encode_canon( uchar out[32], const ulong cx[4], const ulong cy[4] ) {
  for( int i=0; i<4; i++ ) fd_adx_store8_le( out + 8*i, cy[i] );
  out[31] ^= (uchar)((cx[0] & 1ULL) << 7);
}

/* P := -P: negate X and T in place */
static inline void fd_adx_point_neg( fd_ge_adx_t * p ) {
  fd_fe64_neg( p->X, p->X ); fd_fe64_neg( p->T, p->T );
}
/* -(table entry Y+X, Y-X, Z, 2dT in the fields X, Y, Z, T): swap Y+X and Y-X, negate 2dT */
static inline void fd_adx_table_neg( fd_ge_adx_t * r, fd_ge_adx_t const * q ) {
  ulong * rw = (ulong *)r; ulong const * qw = (ulong const *)q;  /* word offsets, as the point operations take them */
  memcpy( rw, qw+4, 32 ); memcpy( rw+4, qw, 32 ); memcpy( rw+8, qw+8, 32 ); fd_fe64_neg( rw+12, qw+12 );
}
/* -(affine entry): swap Y+X and Y-X, negate 2dT */
static inline void fd_adx_base_neg( fd_ge_adx_aff_t * r, fd_ge_adx_aff_t const * q ) {
  memcpy( r->YpX, q->YmX, 32 ); memcpy( r->YmX, q->YpX, 32 ); fd_fe64_neg( r->T2d, q->T2d );
}

/* tab[j] = [2j+1]A in table form, j < cnt */
static inline void
fd_adx_odd_table( fd_ge_adx_t tab[], fd_ge_adx_t const * a, int cnt ) {
  fd_ge_adx_t p, p2; memcpy( &p, a, sizeof(p) );
  fd_ge_adx_dbl( &p2, &p );
  fd_ge_adx_to_table( &tab[0], &p );
  for( int j=1; j<cnt; j++ ) { fd_ge_adx_add( &p, &p, &p2 ); fd_ge_adx_to_table( &tab[j], &p ); }
}

/* r = [2^n] a */
static inline void fd_adx_point_dbln( fd_ge_adx_t * r, fd_ge_adx_t const * a, int n ) {
  if( r != a ) memcpy( r, a, sizeof(*r) );
  for( int i=0; i<n; i++ ) fd_ge_adx_dbl( r, r );
}

#define FD_ADX_BASE_BITS (8)
#define FD_ADX_A_BITS    (4)
#define FD_ADX_SPLIT_SEG_CNT   (8)
#define FD_ADX_SPLIT_SEG_BITS  (33)
#define FD_ADX_SPLIT_A_BITS    (3)
#define FD_ADX_SPLIT_A_SEG_CNT (1<<(FD_ADX_SPLIT_A_BITS-1))
#define FD_ADX_SPLIT_A_TBL_CNT (FD_ADX_SPLIT_SEG_CNT*FD_ADX_SPLIT_A_SEG_CNT)
#define FD_ADX_SPLIT_DIGITS    (FD_ADX_SPLIT_SEG_CNT*FD_ADX_SPLIT_SEG_BITS)
/* the cache's per-key table: FD_ADX_SPLIT_A_TBL_CNT entries, one cache line each */
typedef fd_ge_adx_t fd_adx_tbl_t __attribute__((aligned(64)));

/* A from ea and R from er, both always attempted, the two chains interleaved: bit 0 set when A
   decoded, bit 1 when R did */
static inline int fd_adx_point_decode2( fd_ge_adx_t * a, uchar const ea[32], fd_ge_adx_t * r, uchar const er[32] ) { return fd_adx_point_frombytes2( a, ea, r, er ); }
static inline int fd_adx_point_decode1( fd_ge_adx_t * p, uchar const e[32] ) { return fd_adx_point_frombytes( p, e ); }


/* ---- defined by the primitives unit ----------------------------------------------------- */

/* the split table of a: per segment j, the odd multiples of [2^(b j)]a (verify.c) */
void fd_adx_split_table_a( fd_ge_adx_t tbl[], fd_ge_adx_t const * a );
/* r = [k]A + [s]B by wNAF digits: from the odd multiples of A, built on the spot, or from the split
   table of A (verify.c) */
void fd_adx_double_scalar_mul_base( fd_ge_adx_t * r, uchar const k[ 32 ], fd_ge_adx_t const * a, uchar const s[ 32 ] );
void fd_adx_double_scalar_mul_base_split( fd_ge_adx_t * r, uchar const k[ 32 ], fd_ge_adx_t const a_tbl[], uchar const s[ 32 ] );
/* out = the encoding of [s]B, constant time (sign.c) */
void fd_adx_scalar_mul_base_tobytes( uchar out[32], const uchar s[32] );

